import 'package:flutter/material.dart';
import 'package:symphony_core/symphony_core.dart';

/// Theme configuration of the example: a custom seed color and corner
/// radius; light and dark themes are generated by [SymphonyTheme].
const SymphonyThemeConfig exampleThemeConfig = SymphonyThemeConfig(
  seedColor: Color(0xFF4F46E5),
  cornerRadius: 14,
);

/// Light theme.
final ThemeData exampleLightTheme = SymphonyTheme.light(exampleThemeConfig);

/// Dark theme.
final ThemeData exampleDarkTheme = SymphonyTheme.dark(exampleThemeConfig);
